{
  "strategy_id": "agent_practical",
  "strategy_title": "2주 차원·손실 검증 중심 딥러닝 기초 로드맵",
  "summary": "사용자가 제시한 2주, 주 3시간, 예산 0원의 제약 조건을 반영하여, 실서비스 배포나 고비용 도구가 아닌 로컬 파이썬 환경에서 작은 신경망의 입력·출력 차원과 손실 함수 변화를 직접 확인하는 실습에 집중하는 로드맵입니다. 시작점(2단계)을 고려하여 기초 이론 반복을 최소화하고, 즉시 실행 가능한 코드 작성과 결과 표 생성에 시간을 배분했습니다. 검색된 무료 자료(Microsoft Learn)와 도서관 대출 가능한 도서를 활용하여 비용 부담 없이 학습을 진행합니다.",
  "project_goal": "작은 신경망 예제를 통해 입력·출력 차원 구조를 파악하고, 학습 과정에서의 손실 변화 추이를 기록하여 결과표를 산출한다.",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "신경망 구조 정의 및 차원 확인 실습",
      "duration": "1주",
      "focus": "작은 신경망(예: 2-4-1 구조)을 파이썬으로 구현하고, 각 레이어의 입력·출력 차원을 코드 주석 및 출력으로 명시한다."
    },
    {
      "step": 2,
      "title": "손실 변화 추적 및 결과표 작성",
      "duration": "1주",
      "focus": "학습 에포크별 손실 값을 기록하고, 손실 감소 추이를 시각화하거나 표로 정리하여 최종 결과물을 산출한다."
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "구조 이해 및 차원 검증",
      "duration": "1주",
      "focus_goal": "신경망의 각 층(Layer)이 데이터를 어떻게 변환하는지 차원(Dimension) 관점에서 이해한다.",
      "key_actions": [
        "로컬 파이썬 환경에 NumPy 또는 PyTorch/TensorFlow 기본 라이브러리 설치",
        "입력 차원 2, 은닉층 4, 출력 차원 1인 간단한 신경망 클래스 정의",
        "전진 전파(Forward Pass) 과정에서 각 단계의 텐서/행렬 차원을 print로 출력하여 확인",
        "Microsoft Learn의 'Azure에서 기계 학습 시작' 모듈 중 모델 구조 설계 관련 개념만 선택적 참고"
      ],
      "deliverables": [
        "차원 변환 과정을 주석으로 설명한 신경망 구현 코드 1개",
        "각 레이어별 입력/출력 차원을 기록한 텍스트 파일"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_2065fa1a7d7c"
        }
      ],
      "recommended_books": [
        {
          "isbn": "9788997750085"
        }
      ],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "손실 함수 실험 및 결과표 산출",
      "duration": "1주",
      "focus_goal": "학습 과정에서 손실(Loss) 값이 어떻게 변하는지 수치적으로 확인하고 정리한다.",
      "key_actions": [
        "정의한 신경망에 간단한 합성 데이터(또는 작은 공개 데이터셋)를 입력",
        "에포크(Epoch) 10~20회 동안의 손실 값을 리스트로 수집",
        "수집된 손실 값을 CSV 또는 마크다운 표 형식으로 변환",
        "손실 감소 경향이 정상적인지(수렴 여부)를 시각적으로 간단히 점검"
      ],
      "deliverables": [
        "에포크별 손실 값을 기록한 결과표(CSV/MD)",
        "손실 변화 추이를 요약한 1페이지 분량의 학습 로그"
      ],
      "recommended_courses": [
